class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: ReadItem optimization in 9.0 uses point-reads for single-item
        // lookups by id, which is fine, but raw SQL using the old "Discriminator" property
        // must be updated if the model were migrated to "$type". Since we preserved
        // "Discriminator" in OnModelCreating, existing raw SQL continues to work.

        // Breaking change 5: Sync I/O now throws by default in 9.0.
        // Use async methods instead of .ToList() / .SaveChanges().
        var blogs = context.Blogs.ToListAsync().GetAwaiter().GetResult();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChangesAsync().GetAwaiter().GetResult();
    }
}

